def calculate_tax(amount: float) -> float:
    """Existing tax calculator with unit test coverage."""
    return amount * 0.15

import unittest
from existing_module import calculate_tax

class TestTax(unittest.TestCase):
    def test_tax(self):
        self.assertAlmostEqual(calculate_tax(100.0), 15.0)

if __name__ == '__main__':
    unittest.main()
